// Prepare the lead sent by the Zoho workflow rule and build all three emails for this industry.
const TOKEN = 'CHANGE_ME';   // must match the "token" parameter set in the Zoho webhook
const SITE = 'https://themillsglobal.com/';   // checklist PDFs and links are served from here
const SEG = {
  "name": "Automotive",
  "short": "automotive",
  "topic": "vehicle and equipment imports",
  "guide_title": "Automotive, Heavy Equipment and Special-Purpose Vehicles Import Readiness Checklist",
  "pdf": "assets/lead-magnets/industry-automotive-readiness-checklist.pdf",
  "drive": "https://drive.google.com/uc?export=download&id=1h9hfXEYqCB18SN6XoaDJktWWhM4xFMm5",
  "scene": "buying the vehicle first and finding out it is not admissible after",
  "check": "Has someone confirmed the vehicle or equipment can be imported, and what it will really cost with taxes and permits, before you buy?",
  "send": "the make, model and year",
  "v": 17,
  "summary": "Know before you buy: we confirm a vehicle or equipment unit can be imported and what it will really cost once taxes and permits are in, then clear it and deliver it, so no unit is ever stranded at the port.",
  "url": "https://themillsglobal.com/industries-automotive",
  "stuck": [
    {
      "t": "Buying before checking admissibility",
      "d": "Used and special-purpose units can fail eligibility rules after you have paid for them. We check admissibility before you buy, so you never commit to a unit you cannot import."
    },
    {
      "t": "Taxes and permits that change the real cost",
      "d": "Taxes, clearances and permits add to the landed cost and set the timeline. We price them up front, so the number you approve is the number you pay."
    },
    {
      "t": "Delivery after release",
      "d": "Moving oversized or non-running units from port to their final location is a project of its own. We plan the transport before release, so units do not sit accruing port charges."
    }
  ]
};

const b = $input.first().json.body || {};
const clean = (v) => String(v == null ? '' : v).trim();
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const email = clean(b.email).toLowerCase();
// Each lead is signed by Ari or Joshua, chosen from the email address so the same person signs all three emails
const SENDERS = ['Ari', 'Joshua'];
let hsh = 0;
for (const ch of email) hsh = (hsh * 31 + ch.charCodeAt(0)) >>> 0;
const sender = SENDERS[hsh % SENDERS.length];
const valid = clean(b.token) === TOKEN && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && !!clean(b.lead_id);
const out = {
  valid,
  lead_id: clean(b.lead_id),
  email,
  first_name_greeting: clean(b.first_name) || 'there',
  company: clean(b.company),
  segment: SEG.name,
  topic: SEG.topic,
  short: SEG.short,
  scene: SEG.scene,
  check: SEG.check,
  send: SEG.send,
  v: SEG.v,
  sender_name: sender,
  first_name: clean(b.first_name),
  guide_title: SEG.guide_title,
  pdf_url: SEG.drive,   // Google Drive direct download link (works before the website domain is live)
  page_url: SEG.url,
  book_url: SITE + 'book-a-call.html',
  stuck: SEG.stuck
};

